/**
 * Slack Node - Version 2.6
 * Discriminator: resource=channel, operation=member
 */


interface Credentials {
  slackApi: CredentialReference;
  slackOAuth2Api: CredentialReference;
}

/** List members of a conversation */
export type SlackV26ChannelMemberParams = {
  resource: 'channel';
  operation: 'member';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The Slack channel to get the members from
 * @searchListMethod getChannels
 * @default {"mode":"list","value":""}
 */
    channelId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Whether to resolve the data automatically. By default the response only contain the ID to resource.
 * @default false
 */
    resolveData?: boolean | Expression<boolean>;
};

export type SlackV26ChannelMemberOutput = {
  member?: string;
};

export type SlackV26ChannelMemberNode = {
  type: 'n8n-nodes-base.slack';
  version: 2.6;
  config: NodeConfig<SlackV26ChannelMemberParams> & { credentials?: Credentials };
  output?: Items<SlackV26ChannelMemberOutput>;
};